list_trash.code:
import (
	"fmt"
)

resp, err := client.Trash().ListTrash(ctx, map[string]any{
	"type": "Category", "search": "spring", "sort": "name", "order": "asc", "limit": 20,
}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["items"].([]any) {
	item := row.(map[string]any)
	fmt.Println(item["id"], item["type"], item["name"], item["updated"])
}
fmt.Println(body["pagination"].(map[string]any)["total"])

