bulk_restore_trash.code:
import (
	"fmt"
)

resp, err := client.Trash().BulkRestoreTrash(ctx, map[string]any{
	"items": []any{
		map[string]any{"type": "Category", "id": 1234},
		map[string]any{"type": "BlogPost", "id": 99},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
fmt.Println(body["restored"], body["failed"])
for _, row := range body["errors"].([]any) {
	failure := row.(map[string]any)
	fmt.Println(failure["type"], failure["id"], failure["reason"])
}

